public class AreaReport {

    /** A square: the second subclass of Shape2D. */
    public static class SquareShape extends Shape2D {

        private final double side;

        public SquareShape(double side) {
            super("square");
            this.side = side;
        }

        @Override
        public double area() {
            return side * side;
        }

        @Override
        public double perimeter() {
            return 4 * side;
        }
    }

    public static double totalArea(Shape2D[] shapes) {
        double total = 0.0;
        for (Shape2D shape : shapes) {
            total += shape.area();
        }
        return Math.round(total * 100.0) / 100.0;
    }

    public static String largestName(Shape2D[] shapes) {
        if (shapes.length == 0) {
            return "none";
        }
        Shape2D biggest = shapes[0];
        for (Shape2D shape : shapes) {
            if (shape.area() > biggest.area()) {
                biggest = shape;
            }
        }
        return biggest.getName();
    }

    public static String summary(Shape2D[] shapes) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < shapes.length; i++) {
            if (i > 0) {
                out.append("\n");
            }
            out.append(String.format(java.util.Locale.US, "%s: %.2f",
                                     shapes[i].getName(), shapes[i].area()));
        }
        return out.toString();
    }
}

