public class AreaReportTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }

    public static void main(String[] args) {
        CircleShape circle = new CircleShape(2);
        AreaReport.SquareShape square = new AreaReport.SquareShape(3);

        check("circle name comes from the superclass", "circle", circle.getName());
        check("circle area", 12.57, round2(circle.area()));
        check("circle perimeter override", 12.57, round2(circle.perimeter()));
        check("circle radius getter", 2.0, circle.getRadius());
        check("square name comes from the superclass", "square", square.getName());
        check("square area", 9.0, round2(square.area()));
        check("square perimeter override", 12.0, round2(square.perimeter()));
        check("inherited toString uses the subclass area", "square(9.0)", square.toString());

        Shape2D[] shapes = {circle, square, new AreaReport.SquareShape(1)};
        check("total area of three shapes", 22.57, AreaReport.totalArea(shapes));
        check("largest by area", "circle", AreaReport.largestName(shapes));
        check("largest of an empty array", "none", AreaReport.largestName(new Shape2D[0]));
        check("total of an empty array", 0.0, AreaReport.totalArea(new Shape2D[0]));
        check("summary lines", "circle: 12.57\nsquare: 9.00\nsquare: 1.00",
              AreaReport.summary(shapes));
        check("summary of one shape", "square: 9.00",
              AreaReport.summary(new Shape2D[]{square}));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

